sys_script.script:
(function executeRule(current, previous) {
    // [HackNow critical features] broken_down / under_maintenance are handled by the flow 'FD - Machine - Create Downtime and Start Maintenance'
    // (downtime + maintenance + alert); creating a second downtime here duplicated the record.
    if (current.getValue('status') == 'broken_down' || current.getValue('status') == 'under_maintenance') { return; }
    var machineId = current.getUniqueValue();
    var existingDt = new GlideRecord('x_2056099_indust_0_mach_down');
    existingDt.addQuery('machine', machineId);
    existingDt.addQuery('status', 'active');
    existingDt.query();
    if (existingDt.hasNext()) { return; }

    var status = current.getValue('status');
    var dt = new GlideRecord('x_2056099_indust_0_mach_down');
    dt.initialize();
    dt.setValue('machine', machineId);
    dt.setValue('status', 'active');
    dt.setValue('start_time', new GlideDateTime().getValue());

    if (status === 'broken_down') {
        dt.setValue('downtime_type', 'unplanned');
        dt.setValue('severity', 'critical');
    } else if (status === 'under_maintenance') {
        dt.setValue('downtime_type', 'planned');
        dt.setValue('severity', 'medium');
    } else {
        dt.setValue('downtime_type', 'unplanned');
        dt.setValue('severity', 'major');
    }
    dt.insert();
})(current, previous);
